mapper.select:
select A.* from employee_attendance A
inner join employment_contract C on A.contract_no = C.contract_no
and A.emp_attendance_no = #{empAttendanceNo}
and A.contract_no = #{contractNo}
and A.work_date = #{workDate}
and C.employee_no = #{employeeNo}
and A.attendance_type = 'normal' and A.clock_in is not null and A.clock_out is null

select A.emp_attendance_no, C.employee_no, A.contract_no, A.work_date, A.clock_in, A.clock_out, A.break_minutes, A.attendance_type, S.work_schedule_no,
S.scheduled_day_type as scheduled_work_day_type,
A.night_hours, A.overtime_hours
from employee_attendance A
inner join employment_contract C on A.contract_no = C.contract_no
left join employee_work_schedule S on A.contract_no = S.contract_no and A.work_date = S.scheduled_work_date
where C.employee_no = #{employeeNo}
and A.work_date >= #{startDate}
and A.work_date < #{endDate}
order by A.work_date asc

select * from attendance 
where class_session_no = #{classSessionNo}
  and student_no = #{studentNo}

mapper.update:
UPDATE attendance
SET attendance_state = #{attendanceState},
    attendance_at = #{attendanceAt}
WHERE attendance_no = #{attendanceNo}
